sub_once(p,r"async function writeAllIndexed\(projects\)\{.*?return saved;\}\nfunction writeAll",'''async function writeAllIndexed(projects){if(!Array.isArray(projects))throw new TypeError('Project storage payload must be an array.');const db=await openDatabase(),tx=db.transaction([PROJECTS,META],'readwrite'),store=tx.objectStore(PROJECTS),meta=tx.objectStore(META),seen=new Set(),plans=[],saved=[];try{for(const project of projects){const id=projectIdentity(project);if(!id)throw storageError('Every bulk-written project requires a JOB_ID.','PROJECT_ID_REQUIRED');if(seen.has(id))throw storageError(`Bulk project storage contains duplicate JOB_ID ${id}.`,'DUPLICATE_PROJECT_ID');seen.add(id);const prior=await request(store.get(id)),currentRevision=Number(prior?.revision||0),incomingRevision=Number(project?.revision||0);if(prior&&incomingRevision!==currentRevision)throw storageError(`Project revision conflict for ${id}: expected ${incomingRevision}, found ${currentRevision}.`,'STALE_PROJECT_REVISION');const next=clone(project);next.revision=prior?currentRevision:0;delete next.projectSha256;assertProjectIntegrity(next);let digest=projectSha256(next);if(prior?.projectSha256===digest){next.projectSha256=digest;saved.push(next);continue;}next.revision=prior?currentRevision+1:0;assertProjectIntegrity(next);digest=projectSha256(next);plans.push({id,next,digest});saved.push(next);}fault('during-project-write');for(const plan of plans){store.put({jobId:plan.id,revision:plan.next.revision,project:plan.next,projectSha256:plan.digest,updatedAt:now()});meta.put({key:'selectedProject',value:plan.id,updatedAt:now()});meta.put({key:'lastCommittedRevision',value:{jobId:plan.id,revision:plan.next.revision,projectSha256:plan.digest},updatedAt:now()});}fault('before-transaction-commit');await complete(tx);for(const plan of plans){plan.next.projectSha256=plan.digest;try{new BroadcastChannel('closed-loop-reliability').postMessage({type:'PROJECT_CHANGED',jobId:plan.id,revision:plan.next.revision});}catch{}}return saved;}catch(error){try{tx.abort();}catch{}throw error;}}
function writeAll''',re.S)
