p='verify-browser.mjs'
sub_once(p,r"const userJob='JOB-BROWSER-LEGITIMATE';await evalValue\(cdp,`\(async\(\)=>\{const a=await globalThis\.closedLoopProjectStore\.readAll\(\),p=structuredClone\(a\[0\]\);p\.isRetainedTestProject=false;p\.retainedSpecRevision='';p\.job\.JOB_ID='\$\{userJob\}';p\.job\.JOB_TITLE='Legitimate Browser Project';p\.revision=0;delete p\.projectSha256;p\.stages\[1\]\.status='NOT STARTED';p\.job\.CURRENT_STAGE='STAGE 01';p\.projectData\.sources=\[\];await globalThis\.closedLoopProjectStore\.writeAll\(\[\.\.\.a,p\]\);location\.reload\(\);return true\}\)\(\)`\);", "const userJob='JOB-BROWSER-LEGITIMATE';await evalValue(cdp,`(async()=>{const a=await globalThis.closedLoopProjectStore.readAll(),p=globalThis.closedLoopCore.createBlankState('${userJob}');p.job.JOB_TITLE='Legitimate Browser Project';globalThis.closedLoopWorkflowEngine.ensureShape(p);globalThis.closedLoopWorkflowEngine.recalculate(p);await globalThis.closedLoopProjectStore.writeAll([...a,p]);location.reload();return true})()`);")

