sub_once(p,r"  assert\(staleAttempt\?\.accepted===false&&staleAttempt\.code==='STALE_PROJECT_REVISION','Second-tab stale project revision was accepted\.'\);tab2\.close\(\);","  assert(staleAttempt?.accepted===false&&staleAttempt.code==='STALE_PROJECT_REVISION','Second-tab stale project revision was accepted.');\n  const semanticWrite=await evalValue(cdp,`(async()=>{const store=closedLoopProjectStore,jobId=${JSON.stringify(sharedJob)},p=(await store.readAll()).find(x=>x.job?.JOB_ID===jobId),revision=p.revision;p.job.CURRENT_STAGE='STAGE 30';try{await store.writeProject(p,{expectedProjectRevision:revision});return {accepted:true};}catch(e){return {accepted:false,code:e.code||'',message:e.message};}})()`);\n  assert(semanticWrite?.accepted===false&&semanticWrite.code==='PROJECT_INTEGRITY_FAILED','Semantically impossible canonical project state was persisted.');\n  const bulkAtomic=await evalValue(cdp,`(async()=>{const store=closedLoopProjectStore,all=await store.readAll(),stale=${JSON.stringify(starting.project)},other=all.find(x=>x.job?.JOB_ID!==${JSON.stringify(sharedJob)});if(!other)return {skipped:true};const otherId=other.job.JOB_ID,otherRevision=other.revision;other.job.JOB_TITLE='MUST NOT COMMIT';stale.job.JOB_TITLE='MUST NOT COMMIT STALE';let code='';try{await store.writeAll([other,stale]);}catch(e){code=e.code||'';}const after=await store.readAll(),afterOther=after.find(x=>x.job?.JOB_ID===otherId),afterShared=after.find(x=>x.job?.JOB_ID===${JSON.stringify(sharedJob)});return {code,otherRevisionSame:afterOther?.revision===otherRevision,otherTitleUnchanged:afterOther?.job?.JOB_TITLE!=='MUST NOT COMMIT',staleTitleUnchanged:afterShared?.job?.JOB_TITLE!=='MUST NOT COMMIT STALE'};})()`);\n  assert(!bulkAtomic?.skipped&&bulkAtomic.code==='STALE_PROJECT_REVISION'&&bulkAtomic.otherRevisionSame&&bulkAtomic.otherTitleUnchanged&&bulkAtomic.staleTitleUnchanged,'Bulk project persistence did not reject stale input atomically.');tab2.close();")

